 3→namespace App\Models;
 4→
 5→// use Illuminate\Contracts\Auth\MustVerifyEmail;
 6→use Database\Factories\UserFactory;
 7→use Illuminate\Database\Eloquent\Attributes\Fillable;
 8→use Illuminate\Database\Eloquent\Attributes\Hidden;
 9→use Illuminate\Database\Eloquent\Factories\HasFactory;
10→use Illuminate\Database\Eloquent\Relations\HasMany;
11→use Illuminate\Foundation\Auth\User as Authenticatable;
12→use Illuminate\Notifications\Notifiable;
13→use Laravel\Fortify\TwoFactorAuthenticatable;
14→
15→#[Fillable(['name', 'email', 'password'])]
16→#[Hidden(['password', 'two_factor_secret', 'two_factor_recovery_codes', 'remember_token'])]
17→class User extends Authenticatable
18→{
19→    /** @use HasFactory<UserFactory> */
20→    use HasFactory, Notifiable, TwoFactorAuthenticatable;
21→
22→    /**
23→     * Get the attributes that should be cast.
24→     *
25→     * @return array<string, string>
26→     */
27→    public function exploitations(): HasMany
28→    {
29→        return $this->hasMany(Exploitation::class);
30→    }
31→
32→    protected function casts(): array
33→    {
34→        return [
35→            'email_verified_at' => 'datetime',
36→            'password' => 'hashed',
37→            'two_factor_confirmed_at' => 'datetime',
38→        ];
39→    }
40→}
