  6→import { SubExploitationCard } from '@/components/sub-exploitation-card';
  7→import AppLayout from '@/layouts/app-layout';
  8→import { dashboard } from '@/routes';
  9→import type { BreadcrumbItem } from '@/types';
 10→
 11→type SubExploitation = {
 12→    id: number;
 13→    species: string;
 14→    exploitation_type: string;
 15→    zootechnical_classification: string;
 16→    productive_system: string;
 17→    current_capacity: number;
 18→    max_capacity: number;
 19→    sustainability: string | null;
 20→    self_consumption: boolean;
 21→    animals_count: number;
 22→};
 23→
 24→type Exploitation = {
 25→    id: number;
 26→    rega_code: string;
 27→    name: string;
 28→    municipality: string | null;
 29→    province: string | null;
 30→    sub_exploitations: SubExploitation[];
 31→};
 32→
 33→type DashboardProps = {
 34→    exploitation: Exploitation | null;
 35→    unreadRegulationsCount: number;
 36→};
 37→
 38→const breadcrumbs: BreadcrumbItem[] = [
 39→    {
 40→        title: 'Mi Explotación',
 41→        href: dashboard(),
 42→    },
 43→];
 44→
 45→export default function Dashboard() {
 46→    const { exploitation, unreadRegulationsCount } = usePage<{ exploitation: Exploitation | null; unreadRegulationsCount: number }>().props;
 47→    const [activeSpecies, setActiveSpecies] = useState<string | null>(null);
 48→
 49→    const subExploitations = exploitation?.sub_exploitations ?? [];
 50→    const availableSpecies = [...new Set(subExploitations.map((s) => s.species))];
 51→    const filteredSubs = activeSpecies
 52→        ? subExploitations.filter((s) => s.species === activeSpecies)
 53→        : subExploitations;
 54→
 55→    return (
 56→        <AppLayout breadcrumbs={breadcrumbs}>
 57→            <Head title="Mi Explotación" />
 58→            <div className="flex flex-col gap-6 p-6">
 59→                {/* Header */}
 60→                <div className="flex items-start justify-between">
 61→                    <div>
 62→                        <h1 className="text-2xl font-bold">Mi Explotación</h1>
 63→                        {exploitation?.province && (
 64→                            <p className="text-sm font-medium text-muted-foreground">{exploitation.province}</p>
 65→                        )}
 66→                    </div>
 67→                    <NotificationBell count={unreadRegulationsCount} />
 68→                </div>
 69→
 70→                {exploitation ? (
 71→                    <>
 72→                        {/* REGA Card */}
 73→                        <ExploitationCard
 74→                            regaCode={exploitation.rega_code}
 75→                            municipality={exploitation.municipality}
 76→                            province={exploitation.province}
 77→                        />
 78→
 79→                        {/* Species Filter */}
 80→                        {availableSpecies.length > 1 && (
 81→                            <div className="flex flex-col gap-2">
 82→                                <span className="text-xs font-semibold tracking-widest text-neutral-500">
 83→                                    FILTRAR POR ESPECIE
 84→                                </span>
 85→                                <SpeciesFilter
 86→                                    species={availableSpecies}
 87→                                    activeSpecies={activeSpecies}
 88→                                    onSelect={setActiveSpecies}
 89→                                />
 90→                            </div>
 91→                        )}
 92→
 93→                        {/* Subexploitations */}
 94→                        <div className="flex flex-col gap-4">
 95→                            <span className="text-xs font-semibold tracking-widest text-neutral-500">
 96→                                SUBEXPLOTACIONES
 97→                            </span>
 98→                            {filteredSubs.map((sub) => (
 99→                                <SubExploitationCard
100→                                    key={sub.id}
101→                                    id={sub.id}
102→                                    species={sub.species}
103→                                    exploitationType={sub.exploitation_type}
104→                                    zootechnicalClassification={sub.zootechnical_classification}
105→                                    productiveSystem={sub.productive_system}
106→                                    currentCapacity={sub.current_capacity}
107→                                    maxCapacity={sub.max_capacity}
108→                                    sustainability={sub.sustainability}
109→                                    selfConsumption={sub.self_consumption}
110→                                    animalsCount={sub.animals_count}
111→                                />
112→                            ))}
113→                        </div>
114→                    </>
115→                ) : (
116→                    <div className="rounded-lg border-2 border-dashed border-neutral-300 p-8 text-center">
117→                        <p className="text-sm text-muted-foreground">
118→                            No tienes ninguna explotación registrada.
119→                        </p>
120→                    </div>
121→                )}
122→            </div>
123→        </AppLayout>
124→    );
125→}
